async function load(){
 if(DEMO){try{store=JSON.parse(localStorage.getItem(LS))||freshDemo()}catch{store=freshDemo()}for(const t of TABLES)store[t]??=[];currentOwnerId??=store.owners[0]?.id||null;return true}
 const {data:{session},error}=await sb.auth.getSession();if(error)throw error;
 if(!session){remoteUser=null;renderLogin();return false}
 remoteUser=session.user;
 const {data:adminRow,error:adminError}=await sb.from('app_admins').select('user_id').eq('user_id',remoteUser.id).maybeSingle();
 if(adminError)throw Error('Não foi possível conferir suas permissões: '+adminError.message);
 role=adminRow?'admin':'owner';previewAsOwner=false;
 const names=role==='admin'?TABLES:['owners','lots','meter_readings','invoices','payments','announcements','lot_access','owner_members','payment_config','financial_links','solar_participants','solar_transactions','community_items','month_explanations'];
 missingFeatures=[];
 const optional=new Set(['financial_links','fee_rules','solar_participants','solar_transactions','expenses','employee_payouts','allocation_rules','import_batches','community_items','month_reopen_events','improvement_notes','month_explanations']);
 const fetched=await Promise.all(names.map(async t=>{
   const rows=[];let offset=0;for(;;){
    let q=sb.from(t).select('*');
    const keys=t==='lot_access'?['lot_id','owner_id']:t==='owner_members'?['owner_id','user_id']:['id'];
    for(const key of keys)q=q.order(key);
    const {data,error}=await q.range(offset,offset+499);
    if(error){if(optional.has(t)&&['42P01','PGRST205'].includes(error.code)){missingFeatures.push(t);return[t,[]]};throw Error(t+': '+error.message)}
    rows.push(...(data||[]));if((data||[]).length<500)break;offset+=500;
   }return[t,rows];
 }));
 store=Object.fromEntries(fetched);for(const name of TABLES)store[name]??=[];
 if(role==='admin'&&store.periods.some(p=>!Object.hasOwn(p,'water_unit_confirmed')))missingFeatures.push('regras financeiras 0.3');
 const available=accessibleOwners();
 currentOwnerId=role==='owner'?(available.some(o=>o.id===currentOwnerId)?currentOwnerId:available[0]?.id||null):null;
 if(role==='admin'){const {data:cap,error:capError}=await sb.rpc('pontal_capabilities');if(capError||cap?.version!=='0.3.6')missingFeatures.push('atualização consolidada 0.3.6');}
 reportLoadError='';collectiveReports=[];const published=await sb.rpc('pontal_month_reports');if(published.error){reportLoadError='O demonstrativo mensal depende da atualização do banco para 0.3.2.';}else collectiveReports=published.data||[];
 if(role==='admin'){const access=await sb.rpc('pontal_access_overview');if(access.error)missingFeatures.push('painel de acessos 0.3.6');else{accessOverview=access.data||[];accessLoadedAt=new Date().toISOString();}}
 if(role==='admin'&&!store.periods.length)periodId=monthToday();
 else if(store.periods.length&&!store.periods.some(p=>p.id===periodId))periodId=store.periods.slice().sort((a,b)=>b.id.localeCompare(a.id))[0].id;
 return true;
}
async function saveRow(table,row,conflict){
 assertAdmin();
 if(DEMO){if(['owners','lots','periods','meter_readings','invoices','payments','expenses','financial_links','fee_rules','allocation_rules','solar_participants'].includes(table))store.month_explanations=[];const list=store[table]||(store[table]=[]);const key=table==='periods'?'id':table==='payment_config'?'id':'id';const idx=list.findIndex(x=>x[key]===row[key]);if(idx<0)list.push({...row});else list[idx]={...list[idx],...row};saveDemo();return row}
 const q=sb.from(table).upsert(row,conflict?{onConflict:conflict}:{}).select().single();const {data,error}=await q;if(error)throw Error(error.message);return data;
}
async function saveMany(table,rows,conflict){assertAdmin();if(!rows.length)return;if(DEMO){for(const row of rows)await saveRow(table,row);return}
 const {error}=await sb.from(table).upsert(rows,conflict?{onConflict:conflict}:{});if(error)throw Error(error.message);
}
async function deleteRow(table,id){assertAdmin();if(DEMO){store[table]=store[table].filter(x=>x.id!==id);saveDemo();return}const {error}=await sb.from(table).delete().eq('id',id);if(error)throw Error(error.message)}
