// Provisão mensal simples: 13º = 1/12; férias = 1/12 + adicional constitucional de 1/3.
// Encargos patronais e situações trabalhistas específicas exigem cálculo/registro próprios.
function monthlyProvisions(salary){return provisions(salary)}
function feeSuggested(o){return fee({...store,fee_rules:[]},{...o,monthly_fee:null},periodId)}
function feeDue(o){return fee(store,o,periodId)}
function activeExpenses(ym){return (store.expenses||[]).filter(x=>x.start_period<=ym&&x.end_period>=ym)}
function reserveLedger(upTo=periodId){
 const closed=store.periods.filter(p=>p.status==='closed'&&p.id<=upTo);
 const provision13=sum(closed,p=>p.financial_snapshot?.provisions?.thirteenth??sum(store.invoices.filter(i=>i.period_id===p.id),i=>sum((i.items||[]).filter(x=>x.code==='provision13'),x=>x.amount)));
 const provisionVacation=sum(closed,p=>p.financial_snapshot?.provisions?.vacation??sum(store.invoices.filter(i=>i.period_id===p.id),i=>sum((i.items||[]).filter(x=>x.code==='vacation'),x=>x.amount)));
 const paid13=sum(store.employee_payouts.filter(x=>x.type==='13'&&x.period_id<=upTo),x=>x.amount),paidVacation=sum(store.employee_payouts.filter(x=>x.type==='vacation'&&x.period_id<=upTo),x=>x.amount);
 return {provision13:round(provision13),provisionVacation:round(provisionVacation),paid13:round(paid13),paidVacation:round(paidVacation),balance13:round(provision13-paid13),balanceVacation:round(provisionVacation-paidVacation)};
}
function receiptLabel(x){return x.receipt_name?`<button class="btn sm light" data-action="receipt" data-kind="${x.participant_id?'solar':x.type?'payout':'expense'}" data-id="${h(x.id)}">📎 ${h(x.receipt_name)}</button>`:'<span class="mini muted">Não anexado</span>'}
async function prepareReceipt(file){assertAdmin();if(!file||!file.size)return {receipt_path:null,receipt_name:null};
 if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))throw Error('Anexe foto JPG, PNG, WEBP ou PDF.');
 if(file.size>5*1024*1024)throw Error('Comprovante maior que 5 MB. Reduza a imagem antes de enviar.');
 const name=file.name.replace(/[^a-z0-9_.-]/gi,'_').slice(-70);
 if(DEMO){if(file.size>350*1024)throw Error('Na demonstração, anexe imagens de até 350 KB. No banco online, limite de 5 MB.');
  const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});return {receipt_path:content,receipt_name:file.name};}
 const path=`comprovantes/${uuid()}_${name}`;
 const {error}=await sb.storage.from('expense-receipts').upload(path,file,{contentType:file.type,upsert:false,cacheControl:'3600'});
 if(error)throw Error('Não foi possível anexar comprovante: '+error.message);
 return {receipt_path:path,receipt_name:file.name};
}
async function openReceipt(kind,id){assertAdmin();const list=kind==='payout'?store.employee_payouts:kind==='solar'?store.solar_transactions:store.expenses;const row=list.find(x=>x.id===id);if(!row?.receipt_path)return message('Comprovante não encontrado');
 if(DEMO){const a=document.createElement('a');a.href=row.receipt_path;a.download=row.receipt_name||'comprovante';document.body.appendChild(a);a.click();a.remove();return;}
 const {data,error}=await sb.storage.from('expense-receipts').createSignedUrl(row.receipt_path,90);
 if(error)throw Error('Não foi possível acessar o comprovante: '+error.message);
 window.open(data.signedUrl,'_blank','noopener');
}

function monthlyInvoices(month=periodId){return store.invoices.filter(i=>i.period_id===month)}
function ownerInvoices(id){return store.invoices.filter(i=>i.owner_id===id).sort((a,b)=>a.period_id.localeCompare(b.period_id))}
function ownerPayments(id){return store.payments.filter(p=>p.owner_id===id).sort((a,b)=>b.paid_at.localeCompare(a.paid_at))}
function totalCharges(id,upto=null){return sum(store.invoices.filter(i=>i.owner_id===id&&(!upto||i.period_id<=upto)),i=>i.current_amount)}
function totalPayments(id,until=null){return sum(store.payments.filter(p=>p.owner_id===id&&(!until||p.paid_at<=until)),p=>p.amount)}
function ownerBalance(id,upto=null){return balance(store,id,upto,todayISO())}
function scopedAnnouncements(){return store.announcements.filter(a=>adminAllowed()||a.audience==='all'||(a.target_owner_ids||[]).includes(currentOwnerId)).sort((a,b)=>b.created_at.localeCompare(a.created_at))}
function monetaryRow(label,value,detail=''){return{label,amount:round(value),detail}}
function calcMonth(p){return calculate(store,p)}
function monthSummary(){const inv=monthlyInvoices(),monthPay=store.payments.filter(p=>p.paid_at.slice(0,7)===periodId);return {billed:sum(inv,i=>i.current_amount),received:sum(monthPay,p=>p.amount),debt:sum(store.owners,o=>Math.max(0,ownerBalance(o.id))),owners:store.owners.length}}
