async function closeMonth(){assertAdmin();const p=activePeriod();if(!p||p.status==='closed')return;
 const c=calcMonth(p);if(c.errors.length)throw Error(c.errors.join(' '));
 const targets=c.result.filter(r=>r.lots.length||r.total>0);
 if(targets.some(r=>approvedInvoices.get(r.owner.id)!==approvalKey(r)))throw Error('Confira e aprove cada fatura antes de fechar.');
 if(store.invoices.some(i=>i.period_id>=periodId))throw Error('Existem faturas neste mês ou em mês posterior. Recarregue e confira o histórico.');
 if(!confirm('Fechar '+labelMonth(periodId)+' e emitir as faturas conferidas?'))return;
 const issued=new Date().toISOString(), rows=targets.map(r=>({id:uuid(),period_id:periodId,owner_id:r.owner.id,due_date:p.due_date,items:r.items,current_amount:r.total,previous_balance_at_issue:ownerBalance(r.owner.id),issued_at:issued,snapshot:{readings:store.meter_readings.find(x=>x.owner_id===r.owner.id&&x.period_id===periodId)||null,owner_name:r.owner.name,lot_numbers:r.lots.map(l=>l.number),provisions:c.provisions,allocation_rules:Object.fromEntries(Object.entries(c.allocationGroups).map(([key,group])=>[key,{weight:group.weights[r.owner.id]||0,quotas:group.quotas,count:group.count,decision:group.decisions[r.owner.id]}])),approved_by:remoteUser?.id||'DEMO'}}));
 const snapshot={transparency:monthlyReport({...p,status:'closed',closed_at:issued},c),allocations:c.allocationSnapshot,provisions:c.provisions,lightingCost:c.lightingCost,energyDifference:c.energyDifference,rate:c.rate,water_divisor:p.water_divisor,version:'0.3.6'};
 if(DEMO){store.invoices.push(...rows);Object.assign(p,{status:'closed',closed_at:issued,financial_snapshot:snapshot});saveDemo()}
 else{const {error}=await sb.rpc('pontal_close_month',{p_period:periodId,p_invoices:rows,p_summary:snapshot,p_source:sourceSnapshot()});if(error)throw Error(error.message)}
 await refresh();message('Mês fechado e faturas emitidas. O envio é feito na tela Comunicação.');
}
