 const previous=[...store.periods].filter(p=>p.id<id).sort((a,b)=>b.id.localeCompare(a.id))[0];
 const p={id,due_date:due(id),status:'draft',energy_rate:num(previous?.energy_rate)||0,general_prev:num(previous?.general_curr),general_curr:num(previous?.general_curr),general_invoice:0,pump_prev:num(previous?.pump_curr),pump_curr:num(previous?.pump_curr),pump_invoice:0,pump_inside_general:previous?.pump_inside_general??null,water_unit_confirmed:false,caretaker_salary_in_fee:previous?.caretaker_salary_in_fee??false,caretaker_energy_prev:num(previous?.caretaker_energy_curr),caretaker_energy_curr:0,caretaker_water_prev:num(previous?.caretaker_water_curr),caretaker_water_curr:0,review_flags:[],water_divisor:num(previous?.water_divisor)||1000,caretaker:num(previous?.caretaker),lighting:0,provision:0,extra_amount:0,extra_scope:'built',solar_per_lot:0,notes:''};
 await saveRow('periods',p);
 const readings=store.owners.map(o=>{const r=store.meter_readings.filter(x=>x.owner_id===o.id&&x.period_id<id).sort((a,b)=>b.period_id.localeCompare(a.period_id))[0];return {id:uuid(),period_id:id,owner_id:o.id,energy_prev:r?.energy_curr??null,energy_curr:null,water_prev:r?.water_curr??null,water_curr:null}});
 await saveMany('meter_readings',readings,'period_id,owner_id');periodId=id;hideModal();await refresh();message('Novo mês criado com leituras anteriores preenchidas.');
