async function saveAllocationRule(form){assertAdmin();const rule=parseRuleForm(form,configApi());await saveRow('allocation_rules',rule);hideModal();await refresh();message('Regra salva. Participantes, cotas e prévias atualizados.');}

let pendingPrivateImport=null;
function privateImportView(){return `<section class="card"><h2>Importar dados reais</h2><p>Selecione o arquivo privado preparado a partir das planilhas. Os dados são enviados somente ao banco autenticado; não inclua esse arquivo nos arquivos públicos do site.</p><button class="btn primary" data-action="privateimport">Selecionar importação privada</button>${(store.import_batches||[]).map(batch=>`<details style="margin-top:14px"><summary>Importação registrada — ${h(batch.source_name)}</summary><ul>${(batch.report?.notes||[]).map(note=>`<li>${h(note)}</li>`).join('')}</ul></details>`).join('')}</section>`;}
function preparePrivateImport(){assertAdmin();if(DEMO)throw Error('Dados reais devem ser importados no banco autenticado. Use a demonstração apenas com exemplos fictícios.');const input=document.createElement('input');input.type='file';input.accept='.json';input.addEventListener('change',async()=>{try{const file=input.files?.[0];if(!file)return;if(file.size>10485760)throw Error('Arquivo maior que10MB.');pendingPrivateImport=validatePayload(JSON.parse(await file.text()));showModal('Conferência da importação privada',importPreview(pendingPrivateImport,h,brl),true);}catch(e){pendingPrivateImport=null;fail(e);}});input.click();}
async function commitPrivateImport(){assertAdmin();if(!pendingPrivateImport)throw Error('Selecione o arquivo privado e confira a prévia.');const payload=pendingPrivateImport;const {data,error}=await sb.rpc('pontal_import_real_data',{p_payload:payload});if(error)throw Error(error.message);if(!data?.ok)throw Error('A importação não foi confirmada pelo banco.');pendingPrivateImport=null;hideModal();await refresh();message(data.already_imported?'Este arquivo já foi importado; nenhum lançamento repetido.':'Dados reais importados em rascunho. Confira os saldos e as pendências do mês.');}

boot();

function ownNotes(){return (store.improvement_notes||[]).filter(n=>n.user_id===(remoteUser?.id||'DEMO'));}
function showNotes(){assertAdmin();showModal('Anotar melhoria',notesHtml(ownNotes(),{h,fmtDate}),true);}
function showNoteForm(id){assertAdmin();const n=id?ownNotes().find(n=>n.id===id):{status:'pending',app_version:'0.3.6',context:titleOf(active)};if(!n)throw Error('Anotação não encontrada.');showModal(id?'Editar melhoria':'Nova melhoria',`<form id="note-form" data-entry-id="${h(n.id||uuid())}"><div class="field"><label>Título</label><input name="title" required maxlength="160" value="${h(n.title)}"></div><div class="field"><label>Problema encontrado</label><textarea name="problem" rows="4" required maxlength="6000">${h(n.problem)}</textarea></div><div class="field"><label>Alteração desejada / objetivo</label><textarea name="suggestion" rows="4" maxlength="6000">${h(n.suggestion)}</textarea></div><div class="form-grid"><div class="field"><label>Situação</label><select name="status">${Object.entries(NOTE_STATUS).map(([v,l])=>`<option value="${v}" ${n.status===v?'selected':''}>${h(l)}</option>`).join('')}</select></div>${field('context','Tela em que ocorreu',n.context||'')}${field('app_version','Versão em uso no registro',n.app_version||'0.3.6')}${field('resolved_version','Versão da conclusão, se concluída',n.resolved_version||'')}</div><div class="field"><label>Resultado / motivo de não ser viável</label><textarea name="resolution" maxlength="6000">${h(n.resolution)}</textarea></div><p class="note">O status é atualizado nesta lista mediante conferência. Não será marcado como concluído automaticamente por instalar uma nova versão.</p><div class="actions"><button class="btn primary" type="submit">Salvar melhoria</button><button class="btn light" type="button" data-action="notes">Voltar às minhas melhorias</button></div></form>`,true);}
async function saveNote(form){assertAdmin();const row={id:form.dataset.entryId,user_id:remoteUser?.id||'DEMO',...getForm(form),updated_at:new Date().toISOString()};for(const key of ['title','problem','suggestion','resolution','resolved_version','context','app_version'])row[key]=(row[key]||'').trim();const errors=noteErrors(row);if(errors.length)throw Error(errors.join(' '));await saveRow('improvement_notes',row);hideModal();await refresh();showNotes();message('Melhoria salva na sua conta.');}

async function publishExplanations(){
 assertAdmin();const p=activePeriod();if(!p||p.status!=='draft')throw Error('Selecione um mês em rascunho.');
 const c=calcMonth(p),report={...monthlyReport(p,c),pending:c.errors.length?['Há '+c.errors.length+' pendência(s) de conferência. Os valores são provisórios e não devem ser pagos com base nesta prévia.']:[]},rows=c.result.filter(r=>r.owner.active!==false&&(r.lots.length||r.total>0)).map(r=>({owner_id:r.owner.id,calculation:draftInvoice(p.id,r.owner.id)}));
 if(!confirm('Disponibilizar a explicação PROVISÓRIA de '+labelMonth(p.id)+' para os condôminos? Não gera faturas e não autoriza pagamento.'+(c.errors.length?' Há pendências de conferência: os valores poderão mudar.':'')))return;
 if(DEMO){store.month_explanations=rows.map(r=>({id:uuid(),period_id:p.id,owner_id:r.owner_id,report,own_calculation:r.calculation,published_at:new Date().toISOString()}));saveDemo();}
 else{const {error}=await sb.rpc('pontal_publish_explanations',{p_period:p.id,p_report:report,p_items:rows,p_source:sourceSnapshot()});if(error)throw Error(error.message);}
 await refresh();message('Explicação provisória disponibilizada. Nenhuma fatura foi emitida.');
}
